(715516, 75839, 20786, '<td valign="top">Would be better without the wick. 3</td>', 'Would be better without the wick. 3', '2004-05-12 23:00:29.000000', NULL, 1),
(715517, 75898, 21683, '<td valign="top">I love this.... but i would not want to see my b.f. in those</td>', 'I love this.... but i would not want to see my b.f. in those', '2004-05-12 23:00:33.000000', NULL, 1),
(715518, 75275, 21683, '<td valign="top">whats with the wick</td>', 'whats with the wick', '2004-05-12 23:01:03.000000', NULL, 1),
