(717810, 74981, 21158, '<td valign="top">I would have liked to see more detail in the open flower..</td>', 'I would have liked to see more detail in the open flower..', '2004-05-14 02:28:11.000000', NULL, 1),
(717811, 75403, 21158, '<td valign="top">magnificent</td>', 'magnificent', '2004-05-14 02:30:16.000000', NULL, 1),
