(719515, 75715, 20407, '<td valign="top">It would be good to see tighter focus on the white flower with the dead ones a less important.</td>', 'It would be good to see tighter focus on the white flower with the dead ones a less important.', '2004-05-15 08:02:08.000000', NULL, 1),
(719519, 76105, 20822, '<td valign="top">Amusing expression on the chased</td>', 'Amusing expression on the chased', '2004-05-15 08:04:39.000000', NULL, 1),
(719523, 74599, 20822, '<td valign="top">Poorly focused. Besides this is staged why would the rich one be sitting outside? Maybe walking by.</td>', 'Poorly focused. Besides this is staged why would the rich one be sitting outside? Maybe walking by.', '2004-05-15 08:06:57.000000', NULL, 1),
(719525, 75973, 20407, '<td valign="top">Good idea. I think the woodgrain distracts from the main interest in the picture.</td>', 'Good idea. I think the woodgrain distracts from the main interest in the picture.', '2004-05-15 08:09:12.000000', NULL, 1),
