(720117, 75401, 20573, '<td valign="top">Nice image, I liked the colors and the use of depth of field. Sharp and clear.</td>', 'Nice image, I liked the colors and the use of depth of field. Sharp and clear.', '2004-05-15 17:55:14.000000', NULL, 1),
(720123, 75854, 20573, '<td valign="top">This picture has great potential, but a minus for the poles in the bottom and the large empty area in top.</td>', 'This picture has great potential, but a minus for the poles in the bottom and the large empty area in top.', '2004-05-15 17:59:23.000000', NULL, 1),
(720124, 75923, 18130, '<td valign="top">lighting on left pretty harsh. use a piece of paper towel over the light source in order to diffuse the light and give it a softer effect. i also would have chosen a different background.</td>', 'lighting on left pretty harsh. use a piece of paper towel over the light source in order to diffuse the light and give it a softer effect. i also would have chosen a different background.', '2004-05-15 17:59:45.000000', NULL, 1),
